"use strict";

/*
 * Localize HTML generated by the feature modules. English XML values are the
 * canonical source strings. Exact matching deliberately leaves firmware data,
 * user profile names, key legends, and raw diagnostic output unchanged.
 */
let renderedTranslationObserver = null;

function populateLanguageSelectors() {
  const html = Object.entries(state.translations)
    .map(
      ([code, strings]) =>
        `<option value="${esc(code)}" ${code === state.language ? "selected" : ""}>${esc(strings.languageName || code)}</option>`,
    )
    .join("");
  document.querySelectorAll(".language-select").forEach((select) => {
    select.innerHTML = html;
    select.setAttribute("aria-label", t("language"));
  });
}

function translationKeyIndex() {
  const index = new Map();
  Object.values(state.translations).forEach((strings) => {
    Object.entries(strings).forEach(([key, value]) => {
      const text = String(value || "").trim();
      if (text) index.set(text, key);
    });
  });
  return index;
}

const renderedTranslationPatterns = Object.freeze([
  [/^Profile (\d+)$/, "profileNumber"],
  [/^Profile (\d+) name$/, "profileNameNumber"],
  [/^Hardware configuration (\d+)$/, "hardwareConfigurationNumber"],
  [/^(\d+) keys$/, "keyCount"],
  [/^Selected: (.+)$/, "selectedMode"],
  [/^Layer (\d+)$/, "layerNumber"],
  [/^(\d+) SLOTS$/, "slotCount"],
  [/^(\d+) MODES$/, "modeCount"],
  [/^(\d+) ASSIGNED$/, "assignedCount"],
  [/^(\d+)\/4 ACTIONS$/, "actionCount"],
  [/^(\d+)\/(\d+) OUTPUTS$/, "outputCount"],
  [/^(\d+) EVENTS$/, "eventCount"],
]);

function translatePatternValue(value) {
  for (const [pattern, key] of renderedTranslationPatterns) {
    const match = value.match(pattern);
    if (!match) continue;
    return match.slice(1).reduce(
      (result, replacement, index) => result.replaceAll(`{${index}}`, replacement),
      t(key),
    );
  }
  return value;
}

function translateVisibleValue(value, index = translationKeyIndex()) {
  const source = String(value || ""),
    trimmed = source.trim(),
    key = index.get(trimmed);
  const translated = key ? t(key) : translatePatternValue(trimmed);
  if (translated === trimmed) return source;
  const start = source.indexOf(trimmed);
  return `${source.slice(0, start)}${translated}${source.slice(start + trimmed.length)}`;
}

function translateElementAttributes(element, index) {
  ["aria-label", "placeholder", "title"].forEach((attribute) => {
    if (!element?.hasAttribute?.(attribute)) return;
    const current = element.getAttribute(attribute),
      translated = translateVisibleValue(current, index);
    if (translated !== current) element.setAttribute(attribute, translated);
  });
}

function translateRenderedContent(root = document.body) {
  if (!root || typeof document.createTreeWalker !== "function") return;
  const index = translationKeyIndex(),
    excluded = (element) => element?.closest?.(".keyboard, .language-select, [data-no-i18n], code, pre, script, style");
  if (root.nodeType === 3) {
    if (!excluded(root.parentElement)) {
      const translated = translateVisibleValue(root.nodeValue, index);
      if (translated !== root.nodeValue) root.nodeValue = translated;
    }
    return;
  }
  if (root.nodeType === 1 && !excluded(root)) translateElementAttributes(root, index);
  const walker = document.createTreeWalker(root, 0x05);
  let node = walker.nextNode();
  while (node) {
    if (node.nodeType === 3 && !excluded(node.parentElement)) {
      const translated = translateVisibleValue(node.nodeValue, index);
      if (translated !== node.nodeValue) node.nodeValue = translated;
    } else if (node.nodeType === 1 && !excluded(node)) {
      translateElementAttributes(node, index);
    }
    node = walker.nextNode();
  }
}

function observeRenderedTranslations() {
  if (renderedTranslationObserver || typeof MutationObserver !== "function" || !document.body) return;
  renderedTranslationObserver = new MutationObserver((records) => {
    records.forEach((record) => {
      if (record.type === "childList")
        record.addedNodes.forEach((node) => {
          if (node.nodeType === 1 || node.nodeType === 3) translateRenderedContent(node);
        });
      else if (record.type === "characterData") translateRenderedContent(record.target);
      else if (record.type === "attributes")
        translateElementAttributes(record.target, translationKeyIndex());
    });
  });
  renderedTranslationObserver.observe(document.body, {
    attributes: true,
    attributeFilter: ["aria-label", "placeholder", "title"],
    characterData: true,
    childList: true,
    subtree: true,
  });
}

function translateStaticPage() {
  document.documentElement.lang = state.language;
  document.querySelectorAll("[data-i18n]").forEach((node) => {
    node.textContent = t(node.dataset.i18n);
  });
  translateRenderedContent(document.body);
  observeRenderedTranslations();
}

function setLanguage(language) {
  if (!state.translations[language]) return;
  state.language = language;
  localStorage.setItem(LANGUAGE_KEY, language);
  populateLanguageSelectors();
  translateStaticPage();
  if (!document.querySelector("#workspace").classList.contains("hidden")) render();
}
